#!/usr/bin/env python3
"""Add draft bindings only for approved price/interest items not already tutored."""
import gzip,hashlib,json
from fractions import Fraction as F
from pathlib import Path
D=Path(__file__).resolve().parent;ROOT=Path(__file__).resolve().parents[3]
STATE=json.loads(gzip.decompress((D/'bulk-state.json.gz').read_bytes()))
def sha(o):return hashlib.sha256(json.dumps(o,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def main():
 audit=json.loads((D/'price38-audit-v0.1.json').read_text());cache={};bindings=[]
 for a in audit['items']:
  if a['status']!='approved' or a['existing_tutoring_binding']:continue
  row=next(r for r in STATE['records'] if r['question_id']==a['question_id'])
  if row['source_file'] not in cache:cache[row['source_file']]={q['id']:q for q in json.loads((ROOT/row['source_file']).read_text())['items']}
  q=cache[row['source_file']][a['question_id']];assert sha(q)==a['source_record_sha256']
  p=a['parameters'];ans=F(a['calculated_answer']);kind=a['source_family']
  if kind=='successive-price':
   base=F(p['starting_price']);up=int(p['increase_percent']);mid=F(p['intermediate_price']);down=int(p['decrease_percent'])
   diagnostic={'prompt':f'Before calculating, what does ₱{int(base)} represent in this story?','choices':[
    {'id':'starting-price','text':'The price before the increase; it is the starting amount.','role':'intended-interpretation','feedback':'That is the reading used by this item: the next sentence says the price rises from the stated amount. Still check that the wording makes this base clear to you.'},
    {'id':'after-increase','text':'The price after the first increase.','role':'base-interpretation-hypothesis','feedback':'The stem presents this amount before it describes the increase. If the wording led you to read it otherwise, pause here: the percentage operation depends on which price is the base.'},
    {'id':'final-price','text':'The price after both changes.','role':'stage-confusion-hypothesis','feedback':'The amount appears before either change is described. Keep starting, intermediate and final prices in separate places.'},
    {'id':'unclear','text':'I am unsure, guessed, or the wording does not make that clear.','role':'uncertain','feedback':'No misconception is inferred. Identify the stated base before doing arithmetic; if it remains unclear, flag the item for editorial review.'}], 'confirmation':'What words in the stem made you choose that interpretation? Did you think this before calculating, or only after seeing these choices?'}
   flow={'concept_family':'successive-percent-change','interpretation_hypothesis':'starting-versus-intermediate-price-confusion','solution':{'steps':[f'Starting price: ₱{int(base)}.',f'Increase amount: {up}% of ₱{int(base)} = ₱{int(mid-base)}.',f'Intermediate price: ₱{int(base)} + ₱{int(mid-base)} = ₱{int(mid)}.',f'The decrease is applied to ₱{int(mid)}, not the starting price: {down}% of ₱{int(mid)} = ₱{int(mid*down/100)}.',f'Final price: ₱{int(mid)} − ₱{int(mid*down/100)} = ₱{int(ans)}.'], 'hints':['First label the starting amount.','After the increase, write the new intermediate price; the next percentage uses that amount.','Apply the decrease to the intermediate price, then check whether the result is below or above the start.'],'shortcut':'Use multipliers only after naming the base: starting price × (1 + increase rate) × (1 − decrease rate).'} }
  elif kind=='sale-price':
   base=F(p['original_price']);off=int(p['discount_percent']);discount=base*F(off,100)
   diagnostic={'prompt':f'What does the listed ₱{int(base)} represent before you work out {off}% off?','choices':[
    {'id':'original-price','text':'The original price before the discount.','role':'intended-interpretation','feedback':'Correct reading. The discount is a portion of this original amount; the buyer pays what remains.'},
    {'id':'discount-amount','text':'The peso amount already taken off.','role':'discount-base-hypothesis','feedback':'The stem says the item is priced at this amount, so it is the price before the discount. The discount amount still needs to be found.'},
    {'id':'sale-price','text':'The amount the buyer pays after the discount.','role':'stage-confusion-hypothesis','feedback':'The listed price comes before “% off.” The sale price is the original price minus the discount.'},
    {'id':'unclear','text':'I am unsure, guessed, or selected by mistake.','role':'uncertain','feedback':'No cause is established. Mark the original price first, then decide which portion the buyer pays.'}], 'confirmation':'Was that how you read the original question, or did you choose it after seeing these options?'}
   flow={'concept_family':'sale-price-from-original-base','interpretation_hypothesis':'original-price-versus-discount-or-sale-amount','solution':{'steps':[f'Original price: ₱{int(base)}.',f'Discount: {off}% of ₱{int(base)} = ₱{int(discount)}.',f'Buyer pays the remaining {100-off}%: ₱{int(base)} − ₱{int(discount)} = ₱{int(ans)}.'], 'hints':['“% off” describes the part removed from the original price.','Find the discount amount, then subtract it from the original price.'],'shortcut':f'Pay {100-off}% of the original price: ₱{int(base)} × {100-off}/100.'} }
  else:
   principal=F(p['principal']);rate=int(p['annual_rate_percent']);years=F(p['years']);
   diagnostic={'prompt':'Which quantities determine the simple interest asked for here?','choices':[
    {'id':'principal-rate-time','text':'The amount borrowed, the yearly rate, and the time in years.','role':'correct-rule','feedback':'Yes. Simple interest uses the principal, annual rate and time measured in years.'},
    {'id':'add-percent','text':'Add the rate percentage to the amount borrowed.','role':'percent-addition-hypothesis','feedback':'A percentage rate is not a peso amount to add directly. Convert the yearly rate to a fraction of the principal.'},
    {'id':'ignore-months','text':'Use the yearly rate and count only whole years.','role':'time-unit-hypothesis','feedback':'The extra months are part of the time. Convert them to a fraction of a year before multiplying.'},
    {'id':'total-repayment','text':'Add the principal and interest because the question asks for interest.','role':'quantity-target-hypothesis','feedback':'Interest is the borrowing cost only. Principal plus interest would be total repayment, a different quantity.'},
    {'id':'uncertain','text':'I am unsure, guessed, or selected by mistake.','role':'uncertain','feedback':'No cause is established. Separate the principal, annual rate, and total time first.'}], 'confirmation':'Which quantity or step was hardest to interpret? Did this reflect your original method, a guess, or a misclick?'}
   time_text=f"{years.numerator}/{years.denominator}" if years.denominator!=1 else str(years.numerator)
   flow={'concept_family':'simple-interest','interpretation_hypothesis':'annual-rate-or-time-unit-confusion','solution':{'steps':[f'Principal borrowed: ₱{int(principal)}.',f'Annual rate as a decimal: {rate}% = {F(rate,100)}.',f'Time: {time_text} years.',f'Simple interest = principal × rate × time = ₱{int(principal)} × {F(rate,100)} × {time_text} = ₱{int(ans)}.', 'This is the interest only, not the principal plus interest.'], 'hints':['Write the annual rate as a fraction of 1.','Convert months to part of one year.','Multiply principal × annual rate × time; check that the question wants interest, not total repayment.'],'shortcut':'For simple interest, I = P × r × t with r as a decimal and t in years.'} }
  bindings.append({'question_id':q['id'],'source_file':row['source_file'],'source_record_sha256':a['source_record_sha256'],'bank_status_at_authoring':'approved','difficulty':q.get('difficulty'),'language':q.get('language'),'concept_family':flow['concept_family'],'diagnostic_template':kind,'diagnostic':diagnostic,'verified_answer':{'option_id':q['answer_option_id'],'value':str(ans),'unit':'PHP' if kind!='simple-interest' else 'PHP interest','method':a['method'],'source_record_sha256':a['source_record_sha256']},'worked_solution':flow['solution'],'transfer':{'approved_question_id':None,'reason':'No approved unfamiliar transfer item has been independently verified for this specific interpretation/operation family.'},'outcome_contract':{'diagnostic_is_assisted':True,'misconception_is_hypothesis_only':True,'confirmation_required_for_persistent_hypothesis':True,'uncertain_or_misclick_assigns_hypothesis':False,'diagnostic_correctness_is_not_mastery':True,'independent_transfer_required_for_mastery':True},'status':'draft','editorial_review':None,'runtime_eligible':False})
 side={'schema_version':'dexter-price38-guide-draft-v0.1','baseline_commit':'2e1127feee2a8e67afe0dc248cf21728053f984d','status':'draft','runtime_eligible':False,'independent_review':None,'learner_evidence':None,'bindings':bindings,'already_covered_ids':[x['question_id'] for x in audit['items'] if x['status']=='approved' and x['existing_tutoring_binding']],'excluded_nonapproved_ids':[x['question_id'] for x in audit['items'] if x['status']!='approved'],'notes':['This is an incremental sidecar: the 20 source-approved items already bound in pilot/math overlays were not regenerated.','The 17 new bindings cover 2 successive-change, 7 sale-price and 8 simple-interest source-approved items; the one draft sale-price source remains excluded.','Successive-price stems name the initial amount indirectly; this tutoring draft asks the learner to state the base before calculating. Human review must decide whether canonical wording is sufficiently clear.','The existing sale-price family includes an exact parameter clone of a draft record; the draft is excluded, not promoted.','All transfer mappings, independent review and learner-evidence fields remain pending.']}
 (D/'price38-guide-draft-v0.1.json').write_text(json.dumps(side,ensure_ascii=False,indent=2)+'\n');print('new draft bindings',len(bindings),'already covered',len(side['already_covered_ids']),'nonapproved excluded',len(side['excluded_nonapproved_ids']))
if __name__=='__main__':main()
